 "content": "def transform(grid):
    # Duplicate the outermost rows and columns; retain inner rows/columns once.
    expanded_rows = []
    for row in grid:
        expanded_rows.append([v for j, v in enumerate(row)
                              for _ in (0, 1) if j in (0, len(row)-1) or _ == 0])
    out = []
    for i, row in enumerate(expanded_rows):
        out.append(row[:])
        if i in (0, len(expanded_rows)-1):
            out.append(row[:])
    return out

